<template>
  <details class="migration-panel" ref="migrationPanel" @toggle="keepActiveVisible">
    <summary>{{ de ? 'LittleFS: Umstellung & Wiederherstellung' : 'LittleFS: migration & restoration' }}</summary>
    <div class="migration-intro"><p>{{ de ? 'Einmalig umstellen oder eine unterbrochene Wiederherstellung fortsetzen. Deine Sicherung bleibt privat; Formatieren braucht weiterhin deine ausdrückliche Bestätigung.' : 'Migrate once or resume an interrupted restoration. Your backup remains private; formatting still needs your explicit confirmation.' }}</p>
      <button type="button" :disabled="busy || blocked || !connected" @click="readStorageStatus">{{ de ? 'Speicherstatus lesen' : 'Read storage status' }}</button></div>
    <p v-if="packedMounted" class="migration-already" role="status"><strong>{{ de ? 'E: verwendet bereits Packed LittleFS.' : 'E: already uses Packed LittleFS.' }}</strong> {{ de ? 'Nicht erneut formatieren. Eine noch offene Wiederherstellung kannst du mit derselben Sicherung fortsetzen. Diese Speicherabfrage allein bestätigt keinen Importabschluss.' : 'Do not format again. Resume any pending restoration with the same backup. This storage query alone does not confirm import completion.' }}</p>
    <p v-if="target?.state.ready" class="migration-already">{{ de ? 'Die letzte Zielabfrage meldet den Import als abgeschlossen.' : 'The last target query reports the import as complete.' }}</p>
    <p v-if="!capacityApproved" class="migration-limit">{{ de ? 'Dieser Prüfstand ist nicht für eine Umstellung freigegeben. Nicht formatieren.' : 'This build is not approved for migration. Do not format.' }}</p>
    <ol class="migration-roadmap" :aria-label="de?'Ablauf der Speicherumstellung':'Storage migration workflow'">
      <li><span aria-hidden="true">1</span><strong>{{ de?'Sicherung':'Backup' }}</strong><small>{{ archive ? (de?'ZIP eingelesen':'ZIP loaded') : (de?'ZIP erstellen oder auswählen':'Create or select ZIP') }}</small></li>
      <li><span aria-hidden="true">2</span><strong>{{ de?'Vorbereiten':'Prepare' }}</strong><small>{{ capacityProof ? (de?'Platzbedarf geprüft':'Capacity checked') : (de?'Platzbedarf und Ziel prüfen':'Check capacity and target') }}</small></li>
      <li><span aria-hidden="true">3</span><strong>{{ de?'Übertragen':'Transfer' }}</strong><small>{{ report?.readyForFinalVerification ? (de?'Übertragen, Abschluss offen':'Transferred, verification pending') : (de?'Fehlende Daten wiederherstellen':'Restore missing data') }}</small></li>
      <li><span aria-hidden="true">4</span><strong>{{ de?'Einmal abschließen':'Finish once' }}</strong><small>{{ completion ? (de?'Abschluss bestätigt':'Completion acknowledged') : (de?'Vollständig prüfen und freigeben':'Verify and seal the import') }}</small></li>
    </ol>
    <p class="migration-time-note">{{ de ? 'Übertragung ohne vollständiges Nachlesen jeder einzelnen Datei. Der verpflichtende Gesamtvergleich erfolgt einmal beim Abschluss. Eine verlässliche Gesamtdauer lässt sich vorab nicht nennen; unten siehst du den tatsächlich erreichten Fortschritt.' : 'Transfer does not fully reread each individual file. The required complete comparison runs once at completion. A reliable total duration cannot be given beforehand; actual progress is shown below.' }}</p>
    <div class="migration-flow">
      <section><h4>{{ de?'1 · Sicherung auswählen':'1 · Choose backup' }}</h4><div class="migration-actions"><button :disabled="busy || blocked || !connected" @click="makeBackup">1 · {{ de ? 'Vollständige Sicherung erstellen' : 'Create full backup' }}</button><button :disabled="busy || !backup" @click="saveBackup">{{ de ? 'ZIP speichern' : 'Save ZIP' }}</button>      <label>{{ de ? '2 · Gespeicherte ZIP erneut auswählen' : '2 · Select the saved ZIP again' }}
        <input type="file" accept=".zip,application/zip" :disabled="busy || blocked" @change="loadSaved" />
      </label></div></section>
      <section><h4>{{ de?'2 · Umstellung vorbereiten':'2 · Prepare migration' }}</h4><p>{{ de?'Bei der erstmaligen Umstellung die gespeicherte Sicherung mit dem bisherigen Gerät abgleichen. Anschließend Platzbedarf simulieren und das Ziel vorbereiten. Ein vorhandener Import wird weiterverwendet.':'For the first migration, compare the saved backup with the original device. Then simulate capacity and prepare the target. Existing imports are reused.' }}</p><div class="migration-actions"><button :disabled="busy || blocked || !connected || !archive" @click="verifySource">{{ de ? 'Quelle vollständig prüfen' : 'Verify complete source' }}</button><label>{{ de?'Firmware für die lokale Platzprüfung':'Firmware for local capacity check' }}<select :value="capacityProfile" @change="changeCapacityProfile($event.target.value)" :disabled="busy || blocked || (target?.state.pending && target?.state.bound)"><option value="current">DE3.55–DE3.66 / 627–638</option><option value="de354">DE3.51–DE3.54 / 623–626</option><option value="de350">DE3.46–DE3.50 / 618–622</option><option value="de345">DE3.45 / 617</option><option value="de344">DE3.42–DE3.44 / 614–616</option><option value="previous">DE3.36–DE3.37 / 608–609</option><option value="legacy">DE3.31–DE3.33 / 603–605</option></select><small>{{ de?'Prüfprofil, keine Aussage über die installierte Firmware.':'Test profile, not a statement of the installed firmware.' }}</small></label><button :disabled="busy || blocked || !archive || !capacityApproved" @click="checkCapacity">{{ de ? 'LittleFS-Belegung lokal simulieren' : 'Simulate LittleFS capacity locally' }}</button><button type="button" class="migration-primary" :disabled="busy || blocked || !connected || !archive || !capacityProof || !prepareAction" @click="prepareNext">{{ prepareLabel }}</button></div></section>
      <section><h4>{{ de?'3 · Daten zurückspielen':'3 · Restore data' }}</h4><p>{{ de?'Nach einem Abbruch dieselbe Sicherung auswählen und fortsetzen. Größenpassende Dateien werden zunächst übersprungen; der Abschlussvergleich bestätigt ihren Inhalt.':'After interruption, select the same backup and resume. Matching-size files are initially skipped; the final comparison confirms their contents.' }}</p><div class="migration-actions"><button :disabled="busy || blocked || !connected || !archive || !capacityProof || !target?.state.pending || target?.state.archiveSha256!==archive.archiveSha256" @click="restore">{{ de ? 'Alle Nutzdaten wiederherstellen / fortsetzen' : 'Restore / resume all user entries' }}</button></div></section>
      <section><h4>{{ de?'4 · Einmal prüfen und abschließen':'4 · Verify once and finish' }}</h4><p>{{ de?'Dieser Schritt vergleicht Dateien, Ordner und alle Rohattribute vollständig und bestätigt danach den Import. Eine zusätzliche Zielprüfung davor ist nicht erforderlich.':'This step fully compares files, folders and raw attributes, then acknowledges the import. An additional target verification beforehand is not required.' }}</p><div class="migration-actions"><button :disabled="busy || blocked || !connected || !capacityProof || target?.state.ready || target?.state.archiveSha256!==archive?.archiveSha256" @click="finish">{{ de ? 'Import nach vollständiger Nachprüfung abschließen' : 'Finish import after a fresh complete verification' }}</button><button :disabled="busy || blocked || !connected || !target?.state.ready || !target?.state.rebootRequired" @click="restart">{{ de ? 'Gerät bewusst neu starten …' : 'Explicitly restart device …' }}</button></div></section>
    </div>
    <details class="migration-advanced"><summary>{{ de?'Erweiterte Prüfungen und Wiederherstellung':'Advanced checks and recovery' }}</summary><p>{{ de?'Die separate Zielprüfung ist optional und liest den Bestand zusätzlich vollständig. Die Einzelschritte darunter sind für gezielte Wiederherstellung vorgesehen.':'The separate target check is optional and fully reads the collection again. Individual actions below are for targeted recovery.' }}</p><div class="migration-actions"><button :disabled="busy || blocked || !connected || !archive" @click="verifyTarget">4 · {{ de ? 'LittleFS vollständig nachprüfen' : 'Verify complete LittleFS target' }}</button><button :disabled="busy || blocked || !connected || !capacityProof" @click="inspectTarget">{{ de ? '3 · Zielgerät und Importstatus lesen' : '3 · Read target device and import state' }}</button><button :disabled="busy || blocked || !connected || !target || target.state.mounted" @click="formatTarget">{{ de ? 'E: initialisieren / abgebrochenes Format prüfen …' : 'Initialize E: / review interrupted format …' }}</button><button :disabled="busy || blocked || !connected || !target?.state.mounted || !target?.state.pending || target?.state.bound" @click="initialize">{{ de ? 'Leeren Import an diese ZIP binden …' : 'Bind empty import to this ZIP …' }}</button></div></details>
    <details class="migration-help"><summary>{{ de?'Voraussetzungen und Prüfdetails':'Requirements and verification details' }}</summary>    <ol>
      <li>{{ de ? 'Die vollständige Sicherung benötigt Raw128-Zugriff. Die SPIFFS-Vorbereitung 2.22.0-DE3.30-PREP (Zähler 600) ist ausschließlich für die Erstumstellung eines noch mit SPIFFS betriebenen Geräts vorgesehen. Bei bereits installiertem LittleFS die passende LittleFS-Firmware behalten. Eine fehlgeschlagene Speicherabfrage ist kein Grund für einen Firmwarewechsel.' : 'A complete backup requires raw128 access. The SPIFFS preparation 2.22.0-DE3.30-PREP (counter 600) is only intended for the first migration of a device still using SPIFFS. Keep the matching LittleFS firmware on devices already using LittleFS. A failed storage query is not a reason to replace firmware.' }}</li>
      <li>{{ de ? 'Die gespeicherte ZIP-Datei erneut auswählen und jede Quelldatei frisch vergleichen. Der Vergleich allein gibt die Umstellung nicht frei.' : 'Select the saved ZIP again and freshly compare every source file. A matching backup alone does not approve migration.' }}</li>
      <li v-if="!capacityApproved">{{ de ? 'Die Umstellung ist derzeit gesperrt: Der neue Packed-LittleFS-Simulator ist noch nicht freigegeben. Nicht formatieren.' : 'Migration is currently blocked: the new Packed LittleFS simulator is not approved yet. Do not format.' }}</li>
      <li v-else>{{ de ? 'Die vollständige ZIP lokal mit der exakten Packed-LittleFS-Engine simulieren. Auch Zwischenstände und 20 % Platzreserve müssen passen.' : 'Simulate the complete ZIP locally with the exact Packed LittleFS engine. Staging and a 20% storage reserve must fit too.' }}</li>
      <li>{{ de ? 'Nach separat installierter passender Firmware: Gerät und Speicherlayout frisch prüfen. Für den ersten Start ausdrücklich formatieren; nach einem Abbruch den vorhandenen Import ohne weiteres Format fortsetzen.' : 'After separately installing matching firmware: freshly check the device and storage layout. Explicitly format for the first start; after interruption resume the existing import without formatting again.' }}</li>
    </ol>
    <p class="migration-limit">{{ de ? 'Wiederherstellen prüft nur Befehlsbestätigungen und Namenskonflikte. Größenpassende Dateien werden zunächst ungeprüft übersprungen. Ein vollständiger Abschlussvergleich von Bytes, Rohattributen und Bestand bleibt zwingend; erst dann wird der Import freigegeben. Alte unterbrochene Zwischenstände werden vor ihrer Bereinigung kurz gelesen.' : 'Restore checks command acknowledgements and naming conflicts only. Size-matching files are initially skipped without verification. A complete final comparison of bytes, raw attributes and namespace is mandatory before the import is sealed. Old interrupted staging copies are read briefly before cleanup.' }}</p>
    <p class="migration-limit">{{ de ? 'Alte interne Journaldateien .pixl_txn_old/new werden mitgesichert und geprüft, aber wegen möglicher Wiederholung alter Vorgänge nicht zurückgeschrieben. Offene oder unbekannte Journaldateien sperren die Umstellung.' : 'Old internal .pixl_txn_old/new journals are backed up and verified but never restored, to avoid replay. Pending or unknown journals block migration.' }}</p>
    <p class="migration-limit" role="status">{{ de ? 'Die Summe der Dateigrößen ist keine Platzgarantie. Ein erfolgreicher Sicherungsvergleich allein gibt das Formatieren nicht frei. Die Simulation verarbeitet synthetische Dateiinhalte und deine Originalpfade/Rohattribute ausschließlich lokal.' : 'The sum of file sizes is not a capacity guarantee. A successful backup comparison alone does not approve formatting. The simulation processes synthetic file content and your original paths/raw attributes locally only.' }}</p>
    <p v-if="!capacityApproved">{{ de ? 'Historischer Prüfstand: 1.131 Dateien und 77 Ordner passen nicht in die früher geprüften gewöhnlichen LittleFS-Layouts. Der neue Packed-Aufbau muss separat vollständig geprüft werden.' : 'Historical test: 1,131 files and 77 folders did not fit the previously tested ordinary LittleFS layouts. The new packed design requires its own complete verification.' }}</p>
</details>
    <div class="migration-actions migration-utilities"><button :disabled="busy || !report" @click="saveReport">{{ de ? 'Prüfbericht speichern' : 'Save verification report' }}</button><button :disabled="busy || (!archive && !backup && !report)" @click="clear">{{ de ? 'Lokalen Zwischenspeicher leeren' : 'Clear local cached data' }}</button><button v-if="busy" :disabled="cancelling" @click="cancel">{{ cancelling ? (de ? 'Abschluss wird abgewartet …' : 'Waiting for completion …') : (de ? 'Abbrechen' : 'Cancel') }}</button></div>
    <p v-if="filename">{{ filename }}</p>
    <p v-if="archive">{{ archive.fileCount }} {{ de ? 'Dateien' : 'files' }} · {{ archive.directoryCount }} {{ de ? 'Ordner' : 'folders' }} · {{ archive.byteCount }} B · SHA-256 {{ archive.archiveSha256 }}</p>
    <p v-if="capacityProof"><strong>{{ capacityProof.firmwareVersion || capacityProfileLabel }}</strong> · {{ de ? 'Simulation: beobachtete Belegungsspitze' : 'Simulation: observed allocation peak' }} {{ capacityProof.observedPeakUsedBlocks }}/{{ capacityProof.totalBlocks }} · {{ de ? 'konservativer zusätzlicher Transaktionsbedarf' : 'conservative extra transaction allowance' }} {{ capacityProof.transactionAllowance?.additionalBlocks }} {{ de ? 'Blöcke' : 'blocks' }} · {{ de ? 'zusammen höchstens 80 % erlaubt' : 'combined must stay at or below 80%' }} ({{ capacityProof.peakUsedBlocks }}/{{ capacityProof.totalBlocks }}) · {{ de ? 'vollständig nachgelesene Einträge' : 'completely read-back entries' }} {{ capacityProof.verifiedEntries }}</p>
    <p v-if="target" class="migration-limit">{{ target.identity.firmwareVersion }} · {{ de ? 'Anwendungszähler' : 'Application counter' }} {{ target.identity.applicationCounter }} · {{ target.state.ready ? (de?'Import abgeschlossen':'Import complete') : target.state.pending ? (de?'Wiederherstellung ausstehend':'Restoration pending') : (de?'Speicher nicht initialisiert':'Storage not initialized') }} · {{ target.state.bound ? (de?'Gebunden an ZIP: ':'Bound to ZIP: ')+target.state.archiveSha256 : (de?'Noch keine ZIP gebunden':'No ZIP bound yet') }}</p>
    <p role="status" aria-live="polite">{{ status }}</p>
    <p v-if="actionError" class="migration-limit">{{ de ? 'Letzte Aktion nicht vollständig bestätigt:' : 'Latest action not fully confirmed:' }} {{ actionError.code }}. {{ de ? 'Ein früherer Prüfbericht bleibt als Momentaufnahme erhalten.' : 'An earlier verification report remains available as a snapshot.' }}</p>
    <p v-if="completion" class="migration-completed">{{ de ? 'Importabschluss vom Gerät bestätigt.' : 'Import completion acknowledged by the device.' }} {{ de ? 'Dies ist der gespeicherte Abschluss dieser Sicherung, keine aktuelle Verbindungsprüfung.' : 'This records completion of this archive, not a current connection check.' }} · {{ completion.confirmedAt }}<br>SHA-256 {{ completion.verification.archiveSha256 }}
      <button type="button" :disabled="busy" @click="saveCompletionReport">{{ de ? 'Bestätigten Abschlussbericht speichern' : 'Save acknowledged completion report' }}</button>
    </p>
    <div v-if="progress" class="migration-progress"><p>{{ phaseLabel(progress.phase) }} <strong v-if="verificationStep(progress.phase)"> · {{ de ? 'Schritt' : 'Step' }} {{ verificationStep(progress.phase) }}/4</strong> <span v-if="progress.total>0">· {{ progress.done || 0 }}/{{ progress.total }} · {{ verificationStep(progress.phase) ? (de ? 'Teilfortschritt: ' : 'Phase progress: ') : '' }}{{ Math.floor(Math.min(100,(progress.done||0)/progress.total*100)) }}%</span><span v-else> · {{ verificationStep(progress.phase) ? (de ? 'Dieser Prüfschritt läuft ohne Prozentangabe' : 'This verification step has no percentage estimate') : (de?'Gesamtumfang wird ermittelt':'Determining total size') }}</span></p>
      <p v-if="progress.path">{{ progress.path }}</p>
      <p v-if="progress.filePhase" class="migration-file-progress">{{ de?'Aktuelle Datei:':'Current file:' }} {{ phaseLabel(progress.filePhase) }} · {{ progress.fileDone || 0 }}/{{ progress.fileTotal || 0 }} B</p>
      <progress v-if="progress.filePhase && progress.fileTotal>0" :value="progress.fileDone||0" :max="progress.fileTotal" :aria-label="de?'Aktuelle Datei':'Current file'"></progress>
      <p v-if="Number.isSafeInteger(progress.filesDone)">{{ de?'Bisher vollständig gelesen:':'Completely read so far:' }} {{ progress.filesDone }}<span v-if="progress.filesTotal>0"> / {{ progress.filesTotal }}</span> {{ de?'Dateien':'files' }}<span v-if="Number.isFinite(progress.bytesDone)"> · {{ progress.bytesDone }} B</span></p>
      <progress v-if="progress.total>0" :value="progress.done||0" :max="progress.total" :aria-label="verificationStep(progress.phase)?(de?'Teilfortschritt dieses Prüfschritts':'Progress within this verification step'):(de?'Fortschritt':'Progress')"></progress></div>
    <div v-if="report" :class="['migration-report', {ok:report.verified}]">
      <p v-if="report.kind?.includes('verification')">{{ de ? 'Gespeicherte Prüfmomentaufnahme' : 'Saved verification snapshot' }} · {{ report.createdAt || '—' }} · {{ report.firmwareVersion || '—' }}</p>
      <strong>{{ report.verified ? (de ? 'Vollständiger Vergleich stimmt überein' : 'Complete comparison matches') : report.readyForFinalVerification ? (de ? 'Bereit für Abschlussvergleich' : 'Ready for final comparison') : (de ? 'Nicht vollständig bestätigt' : 'Not completely confirmed') }}</strong>
      <p v-if="report.kind && report.kind!=='migration-transfer-complete'">{{ report.kind === 'migration-source-verification' ? (de ? 'Quellsicherung vor dem Umbau' : 'Source backup before migration') : (de ? 'Zielprüfung nach dem Umbau' : 'Target verification after migration') }}</p>
      <p v-if="report.filesVerified !== undefined">{{ report.filesVerified }} {{ de ? 'Dateien frisch gelesen und gehasht' : 'files freshly read and hashed' }} · {{ report.bytesVerified }} B</p>
      <p v-if="repairVerification?.differences?.some(d=>d.reason==='sha256'||d.reason==='size')">{{ de ? 'Beim nächsten Wiederherstellen werden die hier erkannten fehlerhaften Dateien erneut über einen Zwischenstand übertragen. Unbekannte Zusatzdateien werden nicht gelöscht.' : 'The next restore will transfer these mismatching files again through staging. Unknown extra files are never deleted.' }}</p>
      <p v-if="report.differences?.length">{{ report.differences.length }} {{ de ? 'Abweichungen; keine vollständige Wiederherstellung bestätigt.' : 'differences; full restoration is not confirmed.' }}</p>
      <p v-if="report.restoreBlockers?.length">{{ de ? 'Zusätzliche Wiederherstellungssperren trotz archivierter Originaldaten:' : 'Additional restoration blockers despite archived original data:' }} {{ report.restoreBlockers.map(x=>x.path+' · '+x.code).join('; ') }}</p>
      <p v-if="report.excludedArchiveJournals?.length || report.excludedTargetJournals?.length">{{ de ? 'Ausdrücklich ausgenommene interne Journaldateien:' : 'Explicitly excluded internal journal files:' }} {{ [...(report.excludedArchiveJournals||[]),...(report.excludedTargetJournals||[])].join(', ') }}</p>
      <details v-if="report.differences?.length"><summary>{{ de ? 'Abweichungen anzeigen' : 'Show differences' }}</summary><ul><li v-for="(difference,i) in report.differences.slice(0,100)" :key="i">{{ difference.path }} · {{ difference.reason }}</li></ul></details>
    </div>
  </details>
</template>
<script>
import { createMigrationBackup, loadMigrationArchive, verifyMigrationArchive, restoreMigrationArchive, checkMigrationCapacity, retainMigrationSource, inspectMigrationTarget, formatMigrationTarget, initializeMigrationImport, finishMigrationImport, restartAfterMigration } from '../lib/migration.js'
import { getMigrationCapacityTarget } from '../lib/migration-capacity.js'
import { saveBlob } from '../lib/browser-tools.js'
export default {
  props:{connected:Boolean,blocked:Boolean,generation:Number,language:String,getSession:{type:Function,required:true},confirmRestore:{type:Function,required:true},confirmFormat:Function,confirmInitialize:Function,confirmRestart:Function},
  emits:['busy','restored'],
  data:()=>({capacityProfile:'current',storageSnapshot:null,busy:false,cancelling:false,backup:null,archive:null,filename:'',report:null,status:'',progress:null,capacityProof:null,target:null,sourceRetained:null,repairVerification:null,actionError:null,completion:null}),
  computed:{de(){return this.language==='de_DE'},capacityApproved(){return getMigrationCapacityTarget(this.capacityProfile).approved},capacityProfileLabel(){return {current:'DE3.55–DE3.66 / 627–638',de354:'DE3.51–DE3.54 / 623–626',de350:'DE3.46–DE3.50 / 618–622',de345:'DE3.45 / 617',de344:'DE3.42–DE3.44 / 614–616',previous:'DE3.36–DE3.37 / 608–609',legacy:'DE3.31–DE3.33 / 603–605'}[this.capacityProfile]},
    packedMounted(){return this.connected && this.storageSnapshot?.schema===1 && this.storageSnapshot.drive==='E' && this.storageSnapshot.backend===3 && this.storageSnapshot.mounted===true},
    prepareAction(){if(!this.target)return 'inspect';if(!this.target.state.mounted)return 'format';if(this.target.state.pending&&!this.target.state.bound)return 'bind';return null},
    prepareLabel(){const labels={inspect:['Zielgerät prüfen','Check target device'],format:['Speicher einrichten …','Initialize storage …'],bind:['Sicherung für Import bestätigen …','Confirm backup for import …']};return labels[this.prepareAction]?.[this.de?0:1]||(this.target?.state.ready?(this.de?'Import bereits abgeschlossen':'Import already complete'):(this.de?'Für Wiederherstellung vorbereitet':'Prepared for restoration'))}
  },
  watch:{generation(){this.target=null;this.storageSnapshot=null;this.cancel()},connected(value){if(!value){this.target=null;this.storageSnapshot=null;this.cancel()}}},
  beforeUnmount(){this._controller?.abort();this.backup=null;this.archive=null;this.report=null;this.completion=null;this.actionError=null},
  methods:{
    keepActiveVisible(){if(this.busy&&this.$refs.migrationPanel)this.$refs.migrationPanel.open=true},
    changeCapacityProfile(value){if(this.busy||this.blocked||(this.target?.state.pending&&this.target?.state.bound)||!['current','de354','de350','de345','de344','previous','legacy'].includes(value)||value===this.capacityProfile)return;this.capacityProfile=value;this.capacityProof=null;this.target=null;this.status=this.de?'Prüfprofil geändert. Platzbedarf und Ziel erneut prüfen. Es wurde keine Firmware installiert.':'Test profile changed. Recheck capacity and target. No firmware was installed.'},
    async readStorageStatus(){await this.run(async signal=>{await this.options(signal);this.status=this.packedMounted?(this.de?'Packed LittleFS ist auf E: eingehängt. Keine Daten verändert.':'Packed LittleFS is mounted on E:. No data changed.'):(this.de?'Speicherstatus gelesen. Eine abgeschlossene Umstellung wurde damit nicht bestätigt.':'Storage status read. This does not confirm a completed migration.')})},
    async prepareNext(){if(this.busy||this.blocked||!this.connected||!this.archive||!this.capacityProof)return;const action=this.prepareAction;if(action==='inspect')await this.inspectTarget();else if(action==='format')await this.formatTarget();else if(action==='bind')await this.initialize()},
    verificationStep(phase){return {'verify-listing':1,verifying:2,'verify-tree-again':3,'verify-metadata-again':4}[phase]||0},
    phaseLabel(phase){const labels={reading:['Dateien sichern','Backing up files'],scanning:['Bestand erfassen','Reading namespace'],validating:['Sicherung prüfen','Checking backup'],restoring:['Gesamtbestand wiederherstellen','Restore overall collection'],uploading:['Daten schreiben','Writing bytes'],verifying:['Dateiinhalte und Rohattribute prüfen','Verifying contents and raw metadata'],committing:['Datei übernehmen','Committing file'],complete:['Datei übertragen','File transferred'],'transferred-unverified':['Übertragen, noch ungeprüft','Transferred, not yet verified'],'verify-listing':['Vollständigen Bestand erfassen','Reading complete namespace'],'verify-tree-again':['Bestand erneut vergleichen','Comparing namespace again'],'verify-metadata-again':['Alle Rohattribute erneut prüfen','Rechecking every raw attribute']};return labels[phase]?.[this.de?0:1]||phase},
    errorText(error){
      if(error.code==='MIGRATION_PREPARATION_REQUIRED'||error.code==='MIGRATION_CAPABILITY')return this.de?
        'Die benötigten Raw128-Speicherfähigkeiten wurden nicht bestätigt. Neu verbinden und „Speicherstatus lesen“ erneut ausführen. Bleibt der Fehler bestehen, Firmware und Speicherlayout anhand der Diagnose klären. Nicht aufgrund dieser Meldung formatieren oder auf eine SPIFFS-Firmware wechseln. „Ordner sichern (ZIP)“ im normalen Dateimanager bleibt verfügbar; diese normale Sicherung enthält nicht alle 128 Rohbytes.':
        'The required raw128 storage capabilities were not confirmed. Reconnect and retry “Read storage status”. If this persists, use diagnostics to check the firmware and storage layout. Do not format or switch to SPIFFS firmware because of this message. “Back up folder (ZIP)” in the normal file manager remains available; that normal backup does not retain all 128 raw bytes.'
      if(error.code==='MIGRATION_TICKET')return this.de?'Der lokale Wiederherstellungsbeleg ist nicht verfügbar oder passt nicht zu dieser Aktion. Bei einem Browser-Speicherfehler die Aktion erneut starten. Andernfalls prüfen, ob dieselbe ZIP, dasselbe Gerät und das passende Firmware-Prüfprofil gewählt sind; bei laufendem Import dessen Status lesen und die Wiederherstellung fortsetzen. Die gespeicherte ZIP aufbewahren und nicht erneut formatieren.':'The local recovery receipt is unavailable or does not match this action. Retry the action after a browser storage failure. Otherwise check that the same ZIP, device and matching firmware profile are selected; for an existing import, read its status and resume restoration. Retain the saved ZIP and do not format again.'
      if(error.code==='MIGRATION_EXTRA')return this.de?'Wiederherstellung angehalten: Ein zusätzlicher Eintrag oder alter Zwischen-/Backupstand ist nicht sicher dieser Sicherung zuzuordnen. Er bleibt erhalten. Zuerst diesen Wiederherstellungsfall klären; nicht erneut formatieren.':'Restore stopped: an extra entry or previous staging/backup copy cannot safely be attributed to this backup. It was preserved. Resolve this recovery case first; do not format again.'
      return (this.de?'Prüfung angehalten: ':'Verification stopped: ')+(error.code||error.message)
    },
    cancel(){if(this.busy){this.cancelling=true;this._controller?.abort()}},
    clear(){if(this.busy)return;this.backup=null;this.archive=null;this.report=null;this.filename='';this.status='';this.progress=null;this.capacityProof=null;this.target=null;this.sourceRetained=null;this.repairVerification=null;this.actionError=null;this.completion=null},
    async run(action){
      if(this.busy||this.blocked)return
      const previousReport=this.report,previousCompletion=this.completion
      const controller=new AbortController();this._controller=controller;this.busy=true;this.cancelling=false;this.actionError=null;this.progress=null;this.$emit('busy',true);this.keepActiveVisible()
      try{const outcome=await action(controller.signal);if(controller.signal.aborted&&!outcome?.rebootAcknowledged&&!outcome?.sealAcknowledged)throw Object.assign(new Error('Cancelled'),{name:'AbortError'})}
      catch(error){
        this.target=null
        this.status=error.name==='AbortError'?(this.de?'Abgebrochen. Vorherige Prüfberichte und bestätigte Änderungen bleiben erhalten.':'Action cancelled. Previous verification reports and acknowledged changes remain available.'):this.errorText(error)
        this.actionError={code:error.code||error.message,migrationProgress:error.migrationProgress||null,createdAt:new Date().toISOString()}
        // A failed new verification is relevant evidence. A failed later status
        // read/restart is not evidence that an earlier complete comparison failed.
        this.report=error.verification||(this.completion!==previousCompletion?this.completion?.verification:null)||previousReport||{verified:false,error:this.actionError.code,migrationProgress:this.actionError.migrationProgress,createdAt:this.actionError.createdAt}
        if(error.verification)this.repairVerification=error.verification
      }
      finally{if(this._controller===controller){this._controller=null;this.busy=false;this.cancelling=false;this.progress=null;this.$emit('busy',false)}}
    },
    async options(signal){const session=this.getSession();const storageInfo=await session.readStorageInfo();session.assertSession();if(!signal.aborted)this.storageSnapshot={...storageInfo};return {...session,storageInfo,signal,onProgress:p=>{if(!signal.aborted)this.progress={...p,done:p.done??p.bytesDone??0,total:p.total??p.bytesTotal??0}},confirmFormat:this.confirmFormat,confirmInitialize:this.confirmInitialize,confirmRestart:this.confirmRestart}},
    async makeBackup(){await this.run(async signal=>{this.status=this.de?'Laufwerk E: wird vollständig gesichert …':'Backing up all of E: …';const options=await this.options(signal);this.backup=await createMigrationBackup(options);this.status=this.de?'Sicherung erstellt. ZIP speichern, dann die gespeicherte Datei erneut auswählen.':'Backup created. Save the ZIP, then select that saved file again.'})},
    saveBackup(){if(this.backup&&!this.busy)saveBlob(this.backup.blob,this.backup.filename)},
    async loadSaved(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;await this.run(async signal=>{this.archive=null;this.capacityProof=null;this.target=null;this.sourceRetained=null;this.filename='';this.repairVerification=null;this.report=null;this.completion=null;this.status=this.de?'ZIP-Struktur, CRC, Hashes und Wiederherstellbarkeit werden geprüft …':'Checking ZIP structure, CRC, hashes and restore limits …';this.archive=await loadMigrationArchive(file,{signal});this.filename=file.name;this.status=this.de?'Gespeichertes ZIP geprüft. Der vollständige Vergleich mit dem Gerät und die Kapazitätsfreigabe stehen noch aus.':'Saved ZIP validated. Complete comparison and capacity approval are still required.'})},
    async checkCapacity(){if(!this.archive)return;const archive=this.archive;await this.run(async signal=>{this.status=this.de?'Die LittleFS-Belegung wird lokal simuliert …':'Simulating LittleFS capacity locally …';this.capacityProof=null;this.capacityProof=await checkMigrationCapacity(archive,{signal,capacityProfile:this.capacityProfile,onProgress:p=>{this.progress=p}});this.status=this.de?'Lokale Kapazitätssimulation mit Reserve bestanden. Kein Formatieren ausgelöst.':'Local capacity simulation with reserve passed. No formatting was triggered.'})},
    async verifySource(){if(!this.archive)return;const archive=this.archive;await this.run(async signal=>{this.status=this.de?'Quelle wird vollständig gelesen und verglichen …':'Reading and comparing the complete source …';this.sourceRetained=null;this.report=await verifyMigrationArchive({...await this.options(signal),archive});if(this.report.verified&&!this.report.restoreBlockers?.length){this.sourceRetained=await retainMigrationSource({archive,report:this.report});if(!this.sourceRetained.persistent)this.status=this.de?'Quelle geprüft; die ZIP ist nutzbar. Der dauerhafte Browserbeleg konnte nicht gespeichert werden. Initialisieren bleibt gesperrt, bis der lokale Browserspeicher wieder funktioniert.':'Source verified; the ZIP is usable. The durable browser receipt could not be saved. Initialization remains blocked until local browser storage works.';else this.status=this.de?'Alle Quelldaten stimmen mit der erneut eingelesenen Sicherung überein. Prüfbeleg in diesem Browser gespeichert.':'All source data matches the reselected backup. Receipt saved in this browser.'}else this.status=this.de?'Abweichungen oder Wiederherstellungssperren: nicht formatieren.':'Differences or restoration blockers: do not format.'})},
    async inspectTarget(){if(!this.archive||!this.capacityProof)return;await this.run(async signal=>{this.target=null;this.target=await inspectMigrationTarget({...await this.options(signal),archive:this.archive,capacityProof:this.capacityProof});this.status=this.de?'Zielgerät und Importstatus frisch geprüft. Keine Daten verändert.':'Target and import state freshly checked. No data changed.'})},
    async formatTarget(){if(!this.archive||!this.capacityProof)return;await this.run(async signal=>{this.target=null;const options={...await this.options(signal),archive:this.archive,capacityProof:this.capacityProof};await formatMigrationTarget(options);this.target=await inspectMigrationTarget(options);this.status=this.de?'E: ausdrücklich initialisiert. Jetzt den leeren Import an die gespeicherte ZIP binden; kein zweites Format.':'E: explicitly initialized. Bind the empty import to the saved ZIP next; do not format again.'})},
    async initialize(){if(!this.archive||!this.capacityProof)return;await this.run(async signal=>{const options={...await this.options(signal),archive:this.archive,capacityProof:this.capacityProof};await initializeMigrationImport(options);this.target=await inspectMigrationTarget(options);this.status=this.de?'Import an diese ZIP gebunden. Wiederherstellung kann jetzt beginnen oder fortgesetzt werden.':'Import bound to this ZIP. Restoration can start or resume.'})},
    async finish(){
      if(!this.archive||!this.capacityProof||this.target?.state.ready)return
      await this.run(async signal=>{
        this.status=this.de?'Vollständiger Abschlussvergleich läuft: Dateien, Rohattribute und Ordner …':'Running the complete final comparison: bytes, raw attributes and directories …'
        const options={...await this.options(signal),archive:this.archive,capacityProof:this.capacityProof}
        const result=await finishMigrationImport(options)
        this.report=result.verification;this.repairVerification=null
        this.completion=Object.freeze({kind:'acknowledged-migration-completion',confirmedAt:new Date().toISOString(),verification:result.verification,state:{...result.state}})
        // The acknowledged seal is already final. A later refresh can fail or
        // be cancelled without changing the verified outcome that preceded it.
        try{
          this.target=await inspectMigrationTarget(options)
          this.status=this.de?'Import nach frischem vollständigem Vergleich abgeschlossen. Gerät separat neu starten.':'Import sealed after a fresh complete comparison. Restart the device separately.'
        }catch(error){
          this.target=null;this.actionError={code:error.code||error.message,createdAt:new Date().toISOString(),phase:'post-seal-status'}
          this.status=this.de?'Importabschluss und vollständiger Vergleich sind bestätigt. Nur die anschließende Statusabfrage ist offen; Zielstatus erneut lesen. Es ist kein erneuter Import nötig.':'Import completion and the full comparison are acknowledged. Only the subsequent status query is unresolved; read target status again. Another import is not required.'
        }
        return {sealAcknowledged:true}
      })
    },
    async restart(){if(!this.archive||!this.capacityProof)return;await this.run(async signal=>{await restartAfterMigration({...await this.options(signal),archive:this.archive,capacityProof:this.capacityProof});this.status=this.de?'Neustart bestätigt. Das normale Gerätemenü anschließend am Allmiibo prüfen.':'Restart acknowledged. Check the normal menu on Allmiibo afterwards.';return {rebootAcknowledged:true}})},
    async verifyTarget(){if(!this.archive)return;const archive=this.archive;await this.run(async signal=>{this.status=this.de?'Ziel wird vollständig gelesen und verglichen …':'Reading and comparing the complete target …';this.report=await verifyMigrationArchive({...await this.options(signal),archive,target:true});if(!this.report.verified)this.repairVerification=this.report;this.status=this.report.verified?(this.de?'LittleFS-Nutzdaten vollständig bestätigt.':'All LittleFS user data verified.'):(this.de?'Zieldaten weichen ab; Wiederherstellung nicht vollständig.':'Target differs; restoration is incomplete.')})},
    async restore(){if(!this.archive||!this.capacityProof)return;const archive=this.archive,capacityProof=this.capacityProof,repairVerification=this.repairVerification;await this.run(async signal=>{this.status=this.de?'Wiederherstellung wird vorbereitet …':'Preparing restoration …';const options=await this.options(signal);await this.confirmRestore({files:archive.fileCount,root:'E:/',deviceKey:options.deviceKey});options.assertSession();this.status=this.de?'Nutzdaten werden übertragen. Der vollständige Vergleich folgt beim Abschluss.':'Transferring user data. The complete comparison follows at completion.';if(signal.aborted)throw Object.assign(new Error('Cancelled'),{name:'AbortError'});const result=await restoreMigrationArchive({...options,archive,capacityProof,repairVerification,deferFinalVerification:true});this.report=result.verification||(result.deferred?{kind:'migration-transfer-complete',verified:false,readyForFinalVerification:true,completedEntries:result.completed.length,namespace:result.namespace}:null);this.status=result.deferred?(this.de?'Dateien und Rohattribute übertragen; noch nicht inhaltlich geprüft. Bereit für den verpflichtenden Abschlussvergleich: „Import nach vollständiger Nachprüfung abschließen“. Noch nicht vollständig abgeschlossen.':'Files and raw metadata transferred; contents are not verified yet. Ready for the required final comparison: “Finish import after a fresh complete verification”. Not fully completed yet.'):result.verified?(this.de?'Wiederherstellung und vollständiger Vergleich erfolgreich.':'Restoration and complete verification succeeded.'):(this.de?'Übertragung beendet, vollständiger Vergleich fehlgeschlagen.':'Transfer finished, complete verification failed.');this.$emit('restored')})},
    saveCompletionReport(){if(this.completion&&!this.busy)saveBlob(new Blob([JSON.stringify(this.completion,null,2)+'\n'],{type:'application/json'}),'Allmiibo-Migrationsabschluss.json')},
    saveReport(){if(this.report&&!this.busy)saveBlob(new Blob([JSON.stringify(this.report,null,2)+'\n'],{type:'application/json'}),'Allmiibo-Migrationspruefung.json')}
  }
}
</script>
